/* Yolk v1.4: explain screening choices separately from ranking priorities. */
(function(global){
 'use strict';
 const patterns=[
  {name:'Crowded',d:true,c:true,b:true,th:'Demand สูง และมีสาขาทั้งสองฝั่งมาก',en:'High demand, with many branches on both sides.'},
  {name:'FOMO',d:true,c:true,b:false,th:'Demand สูง คู่แข่งมีสาขามาก แต่บางจากยังน้อย',en:'High demand and many competitors; few Bangchak branches.'},
  {name:'Our Farm',d:true,c:false,b:true,th:'Demand สูง บางจากมีฐานสาขา คู่แข่งยังน้อย',en:'High demand and an established Bangchak network; few competitors.'},
  {name:'Pioneer',d:true,c:false,b:false,th:'Demand สูง แต่สาขาทั้งสองฝั่งยังน้อย',en:'High demand, with few branches on either side.'},
  {name:'Quiet',d:false,c:false,b:false,th:'สัญญาณ Demand และสาขาทั้งสองฝั่งยังน้อย',en:'Low measured demand and few branches on either side.'},
  {name:'Their War',d:false,c:true,b:false,th:'คู่แข่งมีสาขามาก แต่ Demand ที่วัดยังต่ำ',en:'Many competitors despite low measured demand; few Bangchak branches.'},
  {name:'Our Island',d:false,c:false,b:true,th:'บางจากมีสาขามาก คู่แข่งน้อย แต่ Demand ที่วัดยังต่ำ',en:'Many Bangchak branches, few competitors and low measured demand.'},
  {name:'Winter War',d:false,c:true,b:true,th:'สาขาทั้งสองฝั่งมาก แต่ Demand ที่วัดยังต่ำ',en:'Many branches on both sides despite low measured demand.'}
 ];
 const icon=n=>global.YolkIcons?.icon(n)||'';
 function pattern(name){return patterns.find(p=>p.name===name)}
 function levels(p,c=Y.criteria,thresholds=false){return `<dl class="pattern-levels"><div><dt>Demand</dt><dd class="${p.d?'level-high':'level-low'}">${p.d?tr('สูง','High'):tr('ต่ำ','Low')}</dd></div><div><dt>${tr('คู่แข่ง','Competitors')}</dt><dd class="${p.c?'level-high':'level-low'}">${p.c?tr('มาก','High'):tr('น้อย','Low')}${thresholds?`<small>${p.c?'≥':'<'} ${c.competitorMany} ${tr('สาขา','branches')}</small>`:''}</dd></div><div><dt>${tr('บางจาก','Bangchak')}</dt><dd class="${p.b?'level-high':'level-low'}">${p.b?tr('มาก','High'):tr('น้อย','Low')}${thresholds?`<small>${p.b?'≥':'<'} ${c.ownMany} ${tr('สาขา','branches')}</small>`:''}</dd></div></dl>`}
 function tierText(a){return a.demand===false?tr('Demand ต่ำ · ไม่จัด Tier','Low demand · no tier'):a.qualifyingTier?'Tier '+a.qualifyingTier:tr('รอข้อมูล Tier','Tier unresolved')}
 function rankText(a,c=Y.criteria){if(c.rankingMode!=='weighted')return Number.isFinite(a.score)?'P'+num(a.score,1):'—';if(!Number.isFinite(a.rankScore))return '—';return num(a.rankScore,1)+(a.rankUpper-a.rankScore>.05?'–'+num(a.rankUpper,1):'')}
 function rankLabel(c=Y.criteria){return c.rankingMode==='weighted'?tr('คะแนนตามน้ำหนัก / 100','Weighted score / 100'):tr('สัญญาณเด่น (P)','Peak signal (P)')}
 function preferred(){return `<section class="section preferred-section" id="preferred-types"><div class="block-title"><h2>${tr('3. รูปแบบทำเลที่สนใจ','3. Preferred location types')}</h2>${icon('bookmark_added')}</div><p>${tr('เลือกว่าทีมอยากศึกษาตลาดแบบไหน โดยดู Demand คู่กับสาขาคู่แข่งและสาขาเรา','Choose the types of market to explore, combining demand with competitor and own supply.')}</p><div class="inline-fields"><div class="field"><label for="demand-mode">${tr('ระดับ Demand ที่รวมไว้','Demand levels to include')}</label><select id="demand-mode"><option value="high" ${draft.demandMode==='high'?'selected':''}>${tr('Demand สูงเท่านั้น','High demand only')}</option><option value="all" ${draft.demandMode==='all'?'selected':''}>${tr('ทั้ง Demand สูงและต่ำ','High and low demand')}</option></select></div><div class="field"><label for="max-demand-tier">${tr('ในกลุ่ม Demand สูง รับ Tier ใดบ้าง','Within high demand, include')}</label><select id="max-demand-tier">${[1,2,3].map(n=>`<option value="${n}" ${draft.maxDemandTier===n?'selected':''}>${n===1?tr('Tier 1 เท่านั้น','Tier 1 only'):n===2?'Tier 1–2':'Tier 1–3'}</option>`).join('')}</select></div></div><p class="rule-caption">${tr('Tier 1 เข้มที่สุด → Tier 3 กว้างที่สุด ใช้ Tier ที่ข้อมูลยืนยันได้ดีที่สุดจากอาคารหรือกิจกรรม ปัจจัยเพิ่มเติมที่ผ่านนับ Tier 3; กลุ่ม Demand ต่ำไม่มี Tier','Tier 1 is the strictest and Tier 3 the broadest. Use the best confirmed building or activity tier. Passing additional signals count as Tier 3; low-demand locations have no tier.')}</p><fieldset class="preferred-fieldset"><legend>${tr('เลือกได้หลายรูปแบบ','Select one or more types')}</legend><div class="preferred-grid">${patterns.map(p=>`<label class="preferred-card ${draft.patterns.includes(p.name)?'is-selected':''}"><span class="preferred-heading"><input type="checkbox" data-pattern="${p.name}" ${draft.patterns.includes(p.name)?'checked':''}><strong>${p.name}</strong><span class="pattern-stars">${'★'.repeat(({Pioneer:3,FOMO:2,'Our Farm':1})[p.name]||0)}</span></span>${levels(p,draft,true)}<span class="pattern-description">${tr(p.th,p.en)}</span>${!p.d&&draft.demandMode==='high'?`<small class="pattern-filter-note">${tr('เปลี่ยนเป็น “ทั้ง Demand สูงและต่ำ” เพื่อรวมแบบนี้','Choose “High and low demand” to include this type.')}</small>`:''}</label>`).join('')}</div></fieldset><p class="footline">${tr('Demand สูง = ผ่านกลุ่มสัญญาณที่เปิดใช้อย่างน้อยหนึ่งกลุ่ม มาก/น้อยของสาขาใช้เกณฑ์ Supply ด้านบน ข้อมูลที่ยังสรุปไม่ได้แยกเป็น “รอตรวจ” ไม่ฝืนจัดประเภท','High demand means at least one enabled signal group qualifies. Supply high/low uses the thresholds above. Unresolved evidence stays in review instead of forcing a type.')}</p><p class="footline">${tr('ดาวเป็นมุมมองกลยุทธ์ตั้งต้น ไม่รับรองยอดขาย และไม่บังคับอันดับเมื่อเลือกเรียงตามน้ำหนัก','Stars express the initial expansion strategy, not a sales forecast. They do not override weighted ranking.')}</p></section>`}
 function weightField(scope,key,label,value){let id='weight-'+scope+'-'+key;return `<div class="weight-row"><label for="${id}">${label}</label><input id="${id}" type="number" min="0" max="100" step="1" inputmode="numeric" data-weight-scope="${scope}" data-weight-key="${key}" value="${value}"><span class="weight-share" data-weight-share="${scope}:${key}"></span></div>`}
 function ranking(){let groups=[{key:'building',label:tr('อาคาร','Buildings'),ids:BUILDING_IDS,enabled:draft.buildingEnabled},{key:'activity',label:tr('กิจกรรม','Activity'),ids:ACTIVITY_IDS,enabled:draft.activityEnabled},{key:'extra',label:tr('ปัจจัยเพิ่มเติม','Additional signals'),ids:draft.extraMetrics,enabled:!!draft.extraMetrics.length}];return `<section class="section ranking-section" id="ranking-weights"><div class="block-title"><h2>${tr('4. น้ำหนักการจัดอันดับ','4. Ranking weights')}</h2>${icon('tune')}</div><p>${tr('เมื่อทำเลผ่านการคัดแล้ว ให้ความสำคัญกับอะไรในการเรียงอันดับ','After screening, decide which factors should lead the ranking.')}</p><div class="field"><label for="ranking-mode">${tr('วิธีเรียงทำเล','Ranking method')}</label><select id="ranking-mode"><option value="weighted" ${draft.rankingMode==='weighted'?'selected':''}>${tr('คะแนนตามน้ำหนักที่ทีมเลือก','Weighted priorities')}</option><option value="legacy" ${draft.rankingMode==='legacy'?'selected':''}>${tr('วิธีเดิม: ดาว → Tier → จำนวนสัญญาณ','Previous: stars → tier → signal count')}</option></select></div>${draft.rankingMode==='legacy'?`<p class="notice">${tr('กำลังใช้วิธีเดิม น้ำหนักด้านล่างจะมีผลเมื่อเลือก “คะแนนตามน้ำหนักที่ทีมเลือก”','The previous method is active. Choose “Weighted priorities” to use the weights below.')}</p>`:''}<fieldset ${draft.rankingMode!=='weighted'?'disabled':''}><legend>${tr('น้ำหนักหลัก','Overall priorities')}</legend><div class="weight-inputs">${weightField('rankingWeights','demand',tr('Demand ในพื้นที่','Local demand'),draft.rankingWeights.demand)}${weightField('rankingWeights','ownGap',tr('โอกาสเพิ่มสาขาบางจาก','Gap in our branch network'),draft.rankingWeights.ownGap)}${weightField('rankingWeights','competitorGap',tr('พื้นที่ที่คู่แข่งยังน้อย','Gap in competitor supply'),draft.rankingWeights.competitorGap)}</div><p class="rule-caption">${tr('ปรับได้ 0–100 ระบบเทียบสัดส่วนให้รวม 100% โดยอัตโนมัติ น้ำหนัก 0 = ไม่ใช้จัดอันดับ แต่ยังใช้เกณฑ์คัดกรองตามเดิม','Use 0–100; values are normalized to 100%. Zero excludes a factor from ranking, while screening rules remain unchanged.')}</p><details class="weight-details"><summary>${icon('tune')}${tr('ปรับน้ำหนักภายใน Demand','Fine-tune demand weights')}</summary><p>${tr('กำหนดน้ำหนักแต่ละกลุ่ม แล้วปรับรายตัววัดภายในกลุ่ม กลุ่มที่ปิดใน Demand จะไม่เข้าคะแนน','Set group weights, then metric weights within each group. Groups disabled in Demand do not enter the score.')}</p>${groups.filter(g=>g.enabled).map(g=>`<div class="weight-group"><h3>${g.label}</h3>${weightField('demandGroupWeights',g.key,tr('น้ำหนักกลุ่ม','Group weight'),draft.demandGroupWeights[g.key])}<div class="metric-weight-list">${g.ids.map(id=>weightField('metricWeights',id,tr(METRIC_INDEX[id].th,METRIC_INDEX[id].en),draft.metricWeights[id])).join('')}</div></div>`).join('')}</details></fieldset><p class="footline">${tr('คะแนน Demand ใช้ Percentile เทียบทั้งประเทศ ส่วนช่องว่างสาขายิ่งมีสาขาน้อยยิ่งได้คะแนนมาก หากข้อมูลไม่ครบจะแสดงช่วงคะแนนและใช้อันดับจากขอบล่าง ไม่แทนข้อมูลที่ขาดด้วยศูนย์','Demand uses national percentiles. Fewer branches give a higher supply-gap score. Incomplete evidence produces a score range; ranking uses its lower bound without treating missing observations as zero.')}</p><p class="footline">${tr('70 / 20 / 10 เป็นค่าเริ่มต้นเพื่อทดลอง ยังไม่ใช่น้ำหนักที่ยืนยันด้วยยอดขาย','70 / 20 / 10 is a starting hypothesis, not a sales-calibrated model.')}</p></section>`}
 function detail(a){let p=pattern(a.pattern);return `<section class="section decision-summary"><div><span class="eyebrow">${tr('เหตุผลที่จัดกลุ่มและเรียงอันดับ','Why this type and rank')}</span><h2>${p?p.name:tr('รอข้อมูลเพื่อจัดประเภท','More evidence needed')}</h2>${p?levels(p,Y.criteria,true)+`<p>${tr(p.th,p.en)}</p>`:''}</div><div class="decision-score"><strong>${rankText(a)}</strong><span>${rankLabel()}</span><b>${tierText(a)}</b><small>${a.demand===true?(a.tierEligible?tr('ผ่าน Tier ที่ทีมเลือก','Meets the selected tier'):tr('ไม่ผ่าน Tier ที่ทีมเลือก','Outside the selected tier')):tr('Tier ใช้เฉพาะกลุ่ม Demand สูง','Tiers apply to high-demand locations')}</small>${Y.criteria.rankingMode==='weighted'?`<p>${tr('คะแนนสำหรับจัดลำดับศึกษาต่อ ไม่ใช่ยอดขายที่คาดการณ์','A research priority score, not a sales forecast.')}</p>`:''}<a class="btn" href="#criteria">${icon('tune')}${tr('ดูเกณฑ์ที่ใช้','View current criteria')}</a></div></section>`}
 function sync(root=document){let c=draft;root.querySelectorAll('[data-weight-share]').forEach(el=>{let [scope,key]=el.dataset.weightShare.split(':'),keys=[];if(scope==='rankingWeights')keys=['demand','ownGap','competitorGap'];else if(scope==='demandGroupWeights')keys=[...(c.buildingEnabled?['building']:[]),...(c.activityEnabled?['activity']:[]),...(c.extraMetrics.length?['extra']:[])];else keys=BUILDING_IDS.includes(key)?BUILDING_IDS:ACTIVITY_IDS.includes(key)?ACTIVITY_IDS:c.extraMetrics;let total=keys.reduce((s,k)=>s+(Number.isFinite(c[scope][k])?c[scope][k]:0),0);el.textContent=total>0&&Number.isFinite(c[scope][key])?num(c[scope][key]/total*100,1)+'%':'—'});}
 global.YolkDecisions={patterns,pattern,levels,preferred,ranking,detail,tierText,rankText,rankLabel,sync};
})(window);
